// GetVRegionFromVDC gets VRegion that VDC belongs to
func GetVRegionFromVDC(vdc string) string {
	vRegion, ok := vdcToVregionMap[vdc]
	if ok {
		return vRegion
	}
	return VREGION_UNKNOWN
}

// GetCurrentVRegion locates current service's VRegion
func GetCurrentVRegion() string {
	return GetVRegionFromVDC(IDC())
}

// GetVRegionFromHost gets VRegion that host belongs to
func GetVRegionFromHost(ip string) string {
	return GetVRegionFromVDC(GetIDCFromHost(ip))
}

// vRegion->vRegion in governance special case
var vRegionToGovernanceRegionMap = map[string]string{
	VREGION_CHINAFINTECH:     VREGION_CHINANORTH,
	VREGION_CHINAAGGREGATION: VREGION_CHINANORTH,
	VREGION_EUROPECENTRAL:    VREGION_SINGAPORECENTRAL,
}

// GetGovernanceVRegionFromVDC Get the region that real governace rules store
func GetGovernanceVRegionFromVDC(vdc string) string {
	vRegion := GetVRegionFromVDC(vdc)
	if ret, exist := vRegionToGovernanceRegionMap[vRegion]; exist {
		return ret
	}
	return vRegion
}
